package run.ikaros.music;
import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.reactive.TransactionalOperator; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; import reactor.core.publisher.Mono;
@Service public class PersistentMusicMetadataCorrectionService implements MusicMetadataCorrectionService { private final MusicMetadataCandidateRepository candidates; private final TransactionalOperator transaction; public PersistentMusicMetadataCorrectionService(MusicMetadataCandidateRepository candidates,TransactionalOperator transaction){this.candidates=candidates;this.transaction=transaction;} @Override public Mono<MusicMetadataCandidateView> update(UUID ownerId,UUID candidateId,UpdateMusicMetadataCandidateRequest request,Long expectedVersion){return candidates.findById(candidateId).filter(c->c.ownerId().equals(ownerId)).switchIfEmpty(Mono.error(new NotFoundException("Metadata Candidate 不存在或无权访问"))).flatMap(current->{long version=current.version()==null?0:current.version();if(expectedVersion!=null&&expectedVersion!=version)return Mono.error(new ConflictException("Metadata Candidate 版本冲突"));if(request.trackNumber()!=null&&request.trackNumber()<1||request.discNumber()!=null&&request.discNumber()<1)return Mono.error(new IllegalArgumentException("曲目号和碟号必须大于 0"));return candidates.save(new MusicMetadataCandidateEntity(current.id(),ownerId,current.trackId(),current.attachmentId(),request.title(),request.artist(),request.album(),request.albumArtist(),request.isrc(),request.genre(),request.trackNumber(),request.discNumber(),request.releaseYear(),"MANUAL",current.createdAt(),Instant.now(),current.version())).map(this::view);}).as(transaction::transactional);} private MusicMetadataCandidateView view(MusicMetadataCandidateEntity e){return new MusicMetadataCandidateView(e.id(),e.trackId(),e.attachmentId(),e.title(),e.artist(),e.album(),e.albumArtist(),e.isrc(),e.genre(),e.trackNumber(),e.discNumber(),e.releaseYear(),e.source(),e.createdAt(),e.updatedAt(),e.version());} }
